16	package org.springframework.samples.petclinic.model;
17	
18	import java.nio.charset.StandardCharsets;
19	import java.security.MessageDigest;
20	import java.security.NoSuchAlgorithmException;
21	import java.time.LocalDate;
22	import java.time.Period;
23	import java.util.Map;
24	
25	/**
26	 * Pure derivations of an {@link Owner}'s read-only attributes.
27	 *
28	 * <p>Each method computes one derived value from an owner's own field values and
29	 * nothing else, so the computations stay stateless and side-effect free. {@link Owner}
30	 * exposes these through thin {@code @Transient} getters that pass in the relevant
31	 * fields; keeping the arithmetic here rather than on the entity leaves {@code Owner}
32	 * to describe its persistent state and relationships while its growing family of
33	 * derived attributes lives together in one place.
34	 */
35	final class OwnerDerivations {
36	
37	    /** Fixed city-to-region table used to derive {@link #region}. */
38	    private static final Map<String, String> CITY_REGION = Map.of(
39	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
40	
41	    /** Region -> inclusive 4-digit postcode range {low, high} used to derive
42	     *  {@link #region} in preference to the city. */
43	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
44	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
45	
46	    private OwnerDerivations() {
47	    }
48	
49	    /**
50	     * The owner's locality, i.e. the canonical region it belongs to. This is read
51	     * from the region-and-hash {@code customerCode} identity: the region is the
52	     * {@code <REGION>} component that precedes the first {@code '-'} of the assigned
53	     * customer code (e.g. {@code NSW} for {@code NSW-9F86D081}). Until an owner has
54	     * been assigned a customer code (for example while its create request is still
55	     * being validated) this falls back to the region derived directly from its own
56	     * fields (see {@link #region(String, String)}).
57	     *
58	     * @return the canonical region string, or {@code "UNKNOWN"}
59	     */
60	    static String locality(String customerCode, String postcode, String city) {
61	        if (customerCode != null) {
62	            int dash = customerCode.indexOf('-');
63	            if (dash >= 0) {
64	                return customerCode.substring(0, dash);
65	            }
66	        }
67	        return region(postcode, city);
68	    }
69	
70	    /**
71	     * The canonical region derived for an owner from its own fields. The postcode is
72	     * consulted first: when it is present and falls within a known region's inclusive
73	     * 4-digit range ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD
74	     * 4000-4099}) that region is returned. Only when the postcode is absent or in no
75	     * known range does this fall back to the fixed city-to-region table
76	     * ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}),
77	     * returning {@code "UNKNOWN"} when the city is not in the table either. This yields
78	     * the same region for the known cities while disambiguating cities that share a name
79	     * via their postcode.
80	     *
81	     * @return the canonical region string, or {@code "UNKNOWN"}
82	     */
83	    static String region(String postcode, String city) {
84	        String byPostcode = regionForPostcode(postcode);
85	        if (byPostcode != null) {
86	            return byPostcode;
87	        }
88	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
89	    }
90	
91	    /**
92	     * The region whose inclusive postcode range contains the given postcode, or
93	     * {@code null} when the postcode is absent, not a four-digit number, or in no
94	     * known range.
95	     */
96	    private static String regionForPostcode(String postcode) {
97	        if (postcode == null || !postcode.matches("\\d{4}")) {
98	            return null;
99	        }
100	        int value = Integer.parseInt(postcode);
101	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
102	            int[] range = entry.getValue();
103	            if (value >= range[0] && value <= range[1]) {
104	                return entry.getKey();
105	            }
106	        }
107	        return null;
108	    }
109	
110	    /**
111	     * Whether the given {@code postcode} is acceptable for the given {@code region}: an
112	     * absent postcode is always accepted, a present postcode must be exactly four
113	     * digits and, when the region has a known inclusive postcode range
114	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}), fall within
115	     * it. A region with no known range (for example {@code "UNKNOWN"}) accepts any
116	     * four-digit postcode.
117	     *
118	     * @return {@code true} if the postcode is absent or valid for the region
119	     */
120	    static boolean postcodeMatchesRegion(String postcode, String region) {
121	        if (postcode == null) {
122	            return true;
123	        }
124	        if (!postcode.matches("\\d{4}")) {
125	            return false;
126	        }
127	        int[] range = REGION_POSTCODES.get(region);
128	        if (range == null) {
129	            return true;
130	        }
131	        int value = Integer.parseInt(postcode);
132	        return value >= range[0] && value <= range[1];
133	    }
134	
135	    /**
136	     * The owner's membership level, a number from 1 to 3 assigned at creation:
137	     * starting at 1, add 1 when an {@code email} is present and add 1 when
138	     * {@code namesakeCount} is 0, capped at 3 (level 4 is reserved for tenure).
139	     *
140	     * @return the membership level, from 1 to 3
141	     */
142	    static int membershipLevel(String email, Integer namesakeCount) {
143	        int level = 1;
144	        if (email != null && !email.isBlank()) {
145	            level++;
146	        }
147	        if (namesakeCount != null && namesakeCount == 0) {
148	            level++;
149	        }
150	        return Math.min(level, 3);
151	    }
152	
153	    /**
154	     * The owner's preferred contact channel: {@code "EMAIL"} when an {@code email}
155	     * is present, otherwise {@code "PHONE"}.
156	     *
157	     * @return {@code "EMAIL"} or {@code "PHONE"}
158	     */
159	    static String contactPreference(String email) {
160	        if (email != null && !email.isBlank()) {
161	            return "EMAIL";
162	        }
163	        return "PHONE";
164	    }
165	
166	    /**
167	     * The Luhn check digit (0-9) computed over the decimal digits contained in the
168	     * given {@code customerCode}, processed right-to-left with every second digit
169	     * doubled (and reduced by 9 when the double exceeds 9). Non-digit characters are
170	     * ignored, and an absent or digit-free customer code yields {@code 0}.
171	     *
172	     * @return the Luhn check digit, from 0 to 9
173	     */
174	    static int checkDigit(String customerCode) {
175	        int sum = 0;
176	        boolean doubleDigit = true;
177	        for (int i = (customerCode == null ? 0 : customerCode.length()) - 1; i >= 0; i--) {
178	            char c = customerCode.charAt(i);
179	            if (c < '0' || c > '9') {
180	                continue;
181	            }
182	            int d = c - '0';
183	            if (doubleDigit) {
184	                d *= 2;
185	                if (d > 9) {
186	                    d -= 9;
187	                }
188	            }
189	            sum += d;
190	            doubleDigit = !doubleDigit;
191	        }
192	        return (10 - (sum % 10)) % 10;
193	    }
194	
195	    /**
196	     * The owner's age band, derived from its {@code birthDate} measured against its
197	     * {@code registrationDate}: {@code "MINOR"} when the owner is under 18 on the
198	     * registration date, {@code "ADULT"} from 18 to 64, and {@code "SENIOR"} at 65 or
199	     * over. The age is the number of whole years between the two dates. Returns
200	     * {@code null} when either date is absent, so no band is reported for an owner
201	     * without a supplied birth date.
202	     *
203	     * @return {@code "MINOR"}, {@code "ADULT"}, {@code "SENIOR"}, or {@code null}
204	     */
205	    static String ageBand(LocalDate birthDate, LocalDate registrationDate) {
206	        if (birthDate == null || registrationDate == null) {
207	            return null;
208	        }
209	        int age = Period.between(birthDate, registrationDate).getYears();
210	        if (age < 18) {
211	            return "MINOR";
212	        }
213	        if (age < 65) {
214	            return "ADULT";
215	        }
216	        return "SENIOR";
217	    }
218	
219	    /**
220	     * The single derived key used for duplicate detection, formed as
221	     * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}.
222	     * The telephone is the owner's stored (E.164-normalised) telephone, the email
223	     * is the stored (lower-cased) email or the empty string when absent, and the
224	     * household component is the stored {@code householdId} or the empty string
225	     * when the owner belongs to no household.
226	     *
227	     * @return the owner's identity key
228	     */
229	    static String identityKey(String telephone, String email, String householdId) {
230	        String tel = telephone == null ? "" : telephone;
231	        String mail = email == null ? "" : email;
232	        String household = householdId == null ? "" : householdId;
233	        return tel + "|" + mail + "|" + household;
234	    }
235	
236	    /**
237	     * The owner's customer code, formatted {@code <REGION>-<HASH8>}: {@code region} is
238	     * the owner's canonical region (see {@link #region(String, String)}) and HASH8 is the
239	     * first eight upper-case hexadecimal characters of the SHA-256 digest of the owner's
240	     * normalised telephone concatenated with its last name (e.g. {@code NSW-9F86D081}).
241	     *
242	     * @return the customer code
243	     */
244	    static String customerCode(String region, String telephone, String lastName) {
245	        String hash8 = sha256Hex(telephone + lastName).substring(0, 8).toUpperCase();
246	        return String.format("%s-%s", region, hash8);
247	    }
248	
249	    /**
250	     * The stable identifier for the household an owner belongs to, derived
251	     * deterministically from its {@code normalizedLastName} and {@code postcode} so that
252	     * every owner sharing a last name and postcode resolves to the same value. It is the
253	     * first twelve lower-case hexadecimal characters of the SHA-256 digest of
254	     * {@code normalizedLastName + '|' + postcode} (an absent postcode contributes the
255	     * empty string).
256	     *
257	     * @return the household identifier
258	     */
259	    static String householdId(String normalizedLastName, String postcode) {
260	        String pc = postcode == null ? "" : postcode;
261	        return sha256Hex(normalizedLastName + "|" + pc).substring(0, 12);
262	    }
263	
264	    /**
265	     * The SHA-256 digest of the UTF-8 bytes of the given value, as a lower-case
266	     * hexadecimal string. Callers take the prefix and case they need.
267	     */
268	    static String sha256Hex(String value) {
269	        try {
270	            byte[] digest = MessageDigest.getInstance("SHA-256")
271	                .digest(value.getBytes(StandardCharsets.UTF_8));
272	            StringBuilder hex = new StringBuilder(digest.length * 2);
273	            for (byte b : digest) {
274	                hex.append(String.format("%02x", b));
275	            }
276	            return hex.toString();
277	        } catch (NoSuchAlgorithmException e) {
278	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
279	        }
280	    }
281	}
